 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    if not points:
        return out

    rows = sorted(r for r, _ in points)
    median_row = rows[(len(rows) - 1) // 2]
    min_col = min(c for _, c in points)
    max_col = max(c for _, c in points)

    # Connect the two central objects horizontally, and every other object
    # vertically to that shared row, using color 3.
    for c in range(min_col, max_col + 1):
        if out[median_row][c] == 0:
            out[median_row][c] = 3
    for r, c in points:
        for rr in range(min(r, median_row), max(r, median_row) + 1):
            if out[rr][c] == 0:
                out[rr][c] = 3
    return out
